package uk.ac.ravensbourne.casevault.web;
import jakarta.servlet.http.HttpServletRequest; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import uk.ac.ravensbourne.casevault.report.ReportService; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.service.CaseRateLimitService;
@RestController @RequestMapping("/cases/{caseId}/reports") public class ReportController { private final ReportService reports; private final CaseRateLimitService rateLimits; public ReportController(ReportService r,CaseRateLimitService l){reports=r;rateLimits=l;} @PostMapping @PreAuthorize("hasRole('SECURITY_ANALYST')") public ResponseEntity<Void> generate(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID caseId,HttpServletRequest request){rateLimits.checkReportGeneration(p,request.getRemoteAddr(),caseId);var r=reports.generate(p,caseId);return ResponseEntity.created(java.net.URI.create("/cases/"+caseId+"/reports/"+r.getId())).build();} @PostMapping("/{id}/submit") @PreAuthorize("hasRole('SECURITY_ANALYST')") public ResponseEntity<Void> submit(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID caseId,@PathVariable UUID id){reports.submit(p,caseId,id);return ResponseEntity.noContent().build();} @GetMapping("/{id}") @PreAuthorize("isAuthenticated()") public ResponseEntity<byte[]> download(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID caseId,@PathVariable UUID id){var r=reports.downloadable(p,caseId,id);return ResponseEntity.ok().contentType(MediaType.TEXT_PLAIN).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=case-report-"+r.getVersion()+".txt").cacheControl(CacheControl.noStore()).body(r.getContent().getBytes(StandardCharsets.UTF_8));} }
